<?php
declare(strict_types=1);
require __DIR__ . '/../includes/db.php';
if(empty($_SESSION['blog_admin_id'])){header('Location: login.php');exit;}
if(($_SESSION['blog_admin_role']??'admin')!=='admin'){http_response_code(403);exit('Bạn không có quyền quản lý nhuận bút.');}
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
$csrf=$_SESSION['csrf'];$error='';$notice='';
function cr_h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){$error='Phiên quản trị hết hạn.';}
 else{try{
  if(($_POST['action']??'')==='add'){
   $mid=(int)($_POST['member_id']??0);$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$type=(string)($_POST['reward_type']??'royalty');$desc=trim((string)($_POST['description']??''));$period=trim((string)($_POST['period_label']??''));
   if($mid<1||$amount===false||$amount==0||!in_array($type,['royalty','bonus','adjustment'],true)||$desc==='')throw new RuntimeException('Vui lòng nhập đủ thông tin và số tiền khác 0.');
   $q=$pdo->prepare("SELECT id FROM members WHERE id=? AND account_type='contributor' AND is_active=1");$q->execute([$mid]);if(!$q->fetchColumn())throw new RuntimeException('CTV không tồn tại hoặc đã bị khóa.');
   $q=$pdo->prepare('INSERT INTO contributor_rewards(member_id,amount,reward_type,description,period_label,created_by_admin_id) VALUES(?,?,?,?,?,?)');$q->execute([$mid,$amount,$type,mb_substr($desc,0,255,'UTF-8'),$period?:null,(int)$_SESSION['blog_admin_id']]);
   require_once __DIR__.'/../includes/notifications.php';td_notify_member($pdo,$mid,'contributor_reward','Bạn có khoản nhuận bút mới','Truyện Đêm ghi nhận khoản '.number_format((float)$amount,0,',','.').'đ: '.$desc,'/contributor-dashboard.php#rewards');$notice='Đã ghi nhận khoản tiền cho CTV.';
  }elseif(($_POST['action']??'')==='paid'){
   $id=(int)($_POST['reward_id']??0);$pdo->beginTransaction();
   $q=$pdo->prepare("UPDATE contributor_rewards SET payment_status='paid',paid_at=NOW() WHERE id=? AND payment_status='pending'");$q->execute([$id]);if(!$q->rowCount())throw new RuntimeException('Khoản này đã thanh toán hoặc không tồn tại.');
   $q=$pdo->prepare('SELECT member_id,amount FROM contributor_rewards WHERE id=?');$q->execute([$id]);$r=$q->fetch();
   if($r){require_once __DIR__.'/../includes/notifications.php';td_notify_member($pdo,(int)$r['member_id'],'contributor_paid','Nhuận bút đã thanh toán','Khoản '.number_format((float)$r['amount'],0,',','.').'đ đã được xác nhận thanh toán.','/contributor-dashboard.php#rewards');}
   $pdo->exec("UPDATE contributor_reward_periods p SET status='paid' WHERE p.status='generated' AND EXISTS (SELECT 1 FROM contributor_reward_period_items i WHERE i.period_id=p.id AND i.reward_id IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM contributor_reward_period_items i LEFT JOIN contributor_rewards cr ON cr.id=i.reward_id WHERE i.period_id=p.id AND (cr.id IS NULL OR cr.payment_status<>'paid'))");
   $pdo->commit();$notice='Đã xác nhận thanh toán.';
  }else throw new RuntimeException('Thao tác không hợp lệ.');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Không thể lưu dữ liệu. Kiểm tra đã chạy database/contributor_rewards.sql chưa.';}}
}
$members=$pdo->query("SELECT id,display_name,email FROM members WHERE account_type='contributor' AND is_active=1 ORDER BY display_name")->fetchAll();
$filter=(string)($_GET['status']??'all');if(!in_array($filter,['all','pending','paid'],true))$filter='all';
$where=$filter==='all'?'':' WHERE r.payment_status=?';$params=$filter==='all'?[]:[$filter];
$sum=$pdo->query("SELECT COALESCE(SUM(CASE WHEN payment_status='pending' THEN amount ELSE 0 END),0) pending,COALESCE(SUM(CASE WHEN payment_status='paid' THEN amount ELSE 0 END),0) paid FROM contributor_rewards")->fetch();
$q=$pdo->prepare("SELECT r.*,m.display_name,m.email FROM contributor_rewards r JOIN members m ON m.id=r.member_id".$where." ORDER BY r.created_at DESC,r.id DESC LIMIT 100");$q->execute($params);$rows=$q->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nhuận bút CTV | Truyện Đêm CMS</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin-white.css?v=20261121-layout2"><link rel="stylesheet" href="../css/admin-cms.css?v=20261121-cms1"></head><body class="admin-theme"><?php include __DIR__.'/_nav.php';?><main class="admin-wrap"><section class="admin-panel admin-wide"><div class="admin-top"><div><h1>Nhuận bút & thưởng CTV</h1><p>Ghi nhận khoản chi, theo dõi công nợ và xác nhận thanh toán.</p></div></div><?php if($notice):?><p class="admin-success"><?=cr_h($notice)?></p><?php endif;?><?php if($error):?><p class="admin-error"><?=cr_h($error)?></p><?php endif;?>
<div class="reward-summary"><article><span>Chờ thanh toán</span><strong><?=number_format((float)$sum['pending'],0,',','.')?>đ</strong></article><article><span>Đã thanh toán</span><strong><?=number_format((float)$sum['paid'],0,',','.')?>đ</strong></article><article><span>CTV đang hoạt động</span><strong><?=count($members)?></strong></article></div>
<div class="reward-form-panel"><h2>＋ Ghi nhận khoản mới</h2><?php if(!$members):?><p>Chưa có CTV đang hoạt động. Hãy cấp quyền trước.</p><?php else:?><form method="post" class="reward-create-form"><input type="hidden" name="csrf" value="<?=cr_h($csrf)?>"><input type="hidden" name="action" value="add"><label>CTV<select name="member_id" required><option value="">Chọn cộng tác viên</option><?php foreach($members as $m):?><option value="<?=(int)$m['id']?>"><?=cr_h($m['display_name'])?> · #<?=(int)$m['id']?></option><?php endforeach;?></select></label><label>Loại khoản<select name="reward_type"><option value="royalty">Nhuận bút</option><option value="bonus">Thưởng</option><option value="adjustment">Điều chỉnh</option></select></label><label>Số tiền (VNĐ)<input type="number" name="amount" step="1" required placeholder="150000"></label><label>Kỳ / tháng<input name="period_label" maxlength="80" placeholder="Tháng 11/2026"></label><label class="reward-desc">Nội dung<input name="description" maxlength="255" required placeholder="Nhuận bút truyện..."></label><button type="submit">Lưu khoản tiền</button></form><?php endif;?></div>
<div class="reward-list-head"><h2>Lịch sử ghi nhận</h2><form method="get"><select name="status" onchange="this.form.submit()"><option value="all" <?=$filter==='all'?'selected':''?>>Tất cả</option><option value="pending" <?=$filter==='pending'?'selected':''?>>Chờ thanh toán</option><option value="paid" <?=$filter==='paid'?'selected':''?>>Đã thanh toán</option></select></form></div><div class="staff-table-wrap"><table><thead><tr><th>Cộng tác viên</th><th>Khoản tiền</th><th>Nội dung</th><th>Ngày ghi nhận</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=cr_h($r['display_name'])?></strong><small>#<?=(int)$r['member_id']?> · <?=cr_h($r['email'])?></small></td><td><strong><?=number_format((float)$r['amount'],0,',','.')?>đ</strong></td><td><?=cr_h(['royalty'=>'Nhuận bút','bonus'=>'Thưởng','adjustment'=>'Điều chỉnh'][$r['reward_type']]??$r['reward_type'])?> · <?=cr_h($r['description'])?><small><?=cr_h($r['period_label'])?></small></td><td><?=cr_h(date('d/m/Y',strtotime($r['created_at'])))?></td><td><span class="reward-status <?=$r['payment_status']?>"><?=$r['payment_status']==='paid'?'Đã thanh toán':'Chờ thanh toán'?></span></td><td><?php if($r['payment_status']==='pending'):?><form method="post" onsubmit="return confirm('Xác nhận đã thanh toán khoản này?')"><input type="hidden" name="csrf" value="<?=cr_h($csrf)?>"><input type="hidden" name="action" value="paid"><input type="hidden" name="reward_id" value="<?=(int)$r['id']?>"><button class="reward-paid-btn" type="submit">Xác nhận trả</button></form><?php else:?><small><?=!empty($r['paid_at'])?cr_h(date('d/m/Y',strtotime($r['paid_at']))):''?></small><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Chưa có khoản nhuận bút nào.</td></tr><?php endif;?></tbody></table></div><p class="reward-note">Hiển thị tối đa 100 khoản mới nhất. Khoản điều chỉnh có thể là số âm hoặc dương.</p></section></main></body></html>